"use client";
import "./orbit-loader.css";

/** Three fine arcs turning at different speeds, for waits of unknown length. */
export function OrbitLoader({
  size = 56,
  color = "#8ab4ff",
  label = "Loading",
  className = "",
}: {
  size?: number;
  color?: string;
  label?: string;
  className?: string;
}) {
  return (
    <span
      role="status"
      aria-label={label}
      className={`forme-orbit-loader ${className}`}
      style={{ width: size, height: size, color }}
    >
      <svg viewBox="0 0 48 48" aria-hidden="true">
        <circle cx="24" cy="24" r="21" pathLength="100" strokeDasharray="28 72" />
        <circle cx="24" cy="24" r="15" pathLength="100" strokeDasharray="20 80" />
        <circle cx="24" cy="24" r="9" pathLength="100" strokeDasharray="34 66" />
      </svg>
    </span>
  );
}

.forme-orbit-loader {
  display: inline-block;
  filter: drop-shadow(0 0 5px currentColor);
}
.forme-orbit-loader svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}
.forme-orbit-loader circle {
  fill: none;
  stroke: currentColor;
  stroke-width: 1.6;
  stroke-linecap: round;
  transform-origin: 50% 50%;
  animation: forme-orbit-spin 2.4s cubic-bezier(0.45, 0.05, 0.55, 0.95) infinite;
}
.forme-orbit-loader circle:nth-child(2) {
  opacity: 0.7;
  animation-duration: 1.8s;
  animation-direction: reverse;
}
.forme-orbit-loader circle:nth-child(3) {
  opacity: 0.45;
  animation-duration: 1.3s;
}
@keyframes forme-orbit-spin {
  to {
    transform: rotate(360deg);
  }
}
@media (prefers-reduced-motion: reduce) {
  .forme-orbit-loader circle {
    animation: forme-orbit-breathe 2.4s ease-in-out infinite;
  }
  @keyframes forme-orbit-breathe {
    50% {
      opacity: 0.25;
    }
  }
}
